/** A weapon pickup: its id (`core.weapon_<weapon>`) and name are its weapon's (this tool checks both). Short, for the menu's first JS. */
const weapon = (weapon: string, respawnSeconds: number, botValue: number, rolls?: false): ItemDefinition => ({ id: `core.weapon_${weapon.slice(5)}`, displayName: CORE_WEAPONS[weapon]!.displayName, effect: { kind: 'weapon', weapon }, respawnSeconds, botValue, ...(rolls === false ? { rolls } : {}) });

